     8→ *  1. Add a parser in ./parsers/ and export it from ./parsers/index.ts
     9→ *  2. Create a card in ./cards/ and export it from ./cards/index.ts
    10→ *  3. Add the type key to ACTIVE_TYPES below and wire it in the switch.
    11→ */
    12→
    13→import React from "react";
    14→import type { ParsedPaymentQr } from "@/lib/qr-analysis";
    15→import PaymentCard from "@/features/qr-detail/components/PaymentCard";
    16→import { View } from "react-native";
    17→import {
    18→  WebsiteCard,
    19→  WifiCard,
    20→  ContactCard,
    21→  EmailCard,
    22→  SmsCard,
    23→  WhatsAppCard,
    24→  PhoneCard,
    25→  LocationCard,
    26→  CryptoCard,
    27→  EventCard,
    28→  EncryptedCard,
    29→  TextCard,
    30→  SocialCard,
    31→} from "./cards";
    32→import { extractBasicPaymentInfo } from "./parsers";
    33→
    34→// ── Type sets ─────────────────────────────────────────────────────────────────
    35→
    36→const GENERIC_TYPES = new Set(["url", "text", "biolink"]);
    37→
    38→/** All types that have a dedicated rich card — anything else renders as WebsiteCard */
    39→const ACTIVE_TYPES = new Set([
    40→  // Structured / non-URL
    41→  "text", "email", "wifi", "contact", "mecard",
    42→  "payment", "upi", "scantopay", "paymentlink",
    43→  "phone", "sms", "location", "event", "calendar",
    44→  "whatsapp", "crypto", "encrypted",
    45→  // Social & URL-based (now fully supported)
    46→  "url", "instagram", "twitter", "youtube", "linkedin",
    47→  "telegram", "facebook", "spotify", "discord", "tiktok",
    48→  "snapchat", "zoom", "calendly", "paypal", "venmo",
    49→  "reviewpage", "menucatalogue", "donation", "razorpay",
    50→  "appdownload", "app", "google_maps",
    51→]);
    52→
    53→/** Types that render via SocialCard (URL-based with platform branding) */
    54→const SOCIAL_TYPES = new Set([
    55→  "instagram", "twitter", "youtube", "linkedin", "telegram",
    56→  "facebook", "spotify", "discord", "tiktok", "snapchat",
    57→  "zoom", "calendly", "paypal", "venmo",
    58→  "reviewpage", "menucatalogue", "donation", "razorpay",
    59→  "appdownload", "app", "google_maps",
    60→]);
    61→
    62→// ── Props ─────────────────────────────────────────────────────────────────────
    63→
    64→interface Props {
    65→  content: string;
    66→  contentType: string;
    67→  parsedPayment: ParsedPaymentQr | null;
    68→  isDeactivated: boolean;
    69→  onOpenContent: () => void;
    70→  hideOpenAction?: boolean;
    71→  templateKey?: string;
    72→}
    73→
    74→// ── Component ─────────────────────────────────────────────────────────────────
    75→
    76→const ContentCard = React.memo(function ContentCard({
    77→  content,
    78→  contentType,
    79→  parsedPayment,
    80→  isDeactivated,
    81→  onOpenContent,
    82→  hideOpenAction,
    83→  templateKey,
    84→}: Props) {
    85→  // Resolve the effective type: templateKey wins unless it's a generic alias
    86→  const rawEffective = (templateKey && !GENERIC_TYPES.has(templateKey))
    87→    ? templateKey
    88→    : contentType;
    89→  const effectiveType = ACTIVE_TYPES.has(rawEffective) ? rawEffective : "url";
    90→
    91→  // ── Payment ────────────────────────────────────────────────────────────────
    92→  if (
    93→    effectiveType === "payment" ||
    94→    effectiveType === "upi" ||
    95→    effectiveType === "scantopay" ||
    96→    effectiveType === "paymentlink"
    97→  ) {
    98→    const isEmv = content.startsWith("000201") || content.startsWith("00020");
    99→    const basic = !parsedPayment ? extractBasicPaymentInfo(content) : null;
   100→    const paymentData: ParsedPaymentQr = parsedPayment ?? (isEmv
   101→      ? {
   102→          app: "emv_generic", appDisplayName: "Bank Merchant QR", appCategory: "emv",
   103→          region: "Regional", recipientId: "", rawContent: content, isAmountPreFilled: false,
   104→        }
   105→      : {
   106→          app: "upi", appDisplayName: "UPI Payment", appCategory: "upi_india", region: "India",
   107→          recipientId: basic?.vpa || "", recipientName: basic?.name,
   108→          amount: basic?.amount, currency: basic?.currency || "INR",
   109→          rawContent: content, isAmountPreFilled: !!basic?.amount, vpa: basic?.vpa,
   110→        });
   111→    return (
   112→      <View>
   113→        <PaymentCard
   114→          parsedPayment={paymentData}
   115→          isDeactivated={isDeactivated}
   116→          onOpenContent={onOpenContent}
   117→        />
   118→      </View>
   119→    );
   120→  }
   121→
   122→  // ── Encrypted ─────────────────────────────────────────────────────────────
   123→  if (effectiveType === "encrypted") {
   124→    return <EncryptedCard content={content} />;
   125→  }
   126→
   127→  // ── Structured protocol types ──────────────────────────────────────────────
   128→  const commonProps = { content, onOpenContent, isDeactivated, hideOpenAction };
   129→
   130→  switch (effectiveType) {
   131→    case "wifi":     return <WifiCard     {...commonProps} />;
   132→    case "contact":
   133→    case "mecard":   return <ContactCard  {...commonProps} />;
   134→    case "email":    return <EmailCard    {...commonProps} />;
   135→    case "sms":      return <SmsCard      {...commonProps} />;
   136→    case "whatsapp": return <WhatsAppCard {...commonProps} />;
   137→    case "phone":    return <PhoneCard    {...commonProps} />;
   138→    case "location":
   139→    case "google_maps":
   140→                     return <LocationCard {...commonProps} />;
   141→    case "crypto":   return <CryptoCard   {...commonProps} />;
   142→    case "event":
   143→    case "calendar": return <EventCard    {...commonProps} />;
   144→    case "text":     return <TextCard content={content} />;
   145→  }
   146→
   147→  // ── Social / platform URL types ────────────────────────────────────────────
   148→  if (SOCIAL_TYPES.has(effectiveType)) {
   149→    return (
   150→      <SocialCard
   151→        content={content}
   152→        contentType={effectiveType}
   153→        onOpenContent={onOpenContent}
   154→        isDeactivated={isDeactivated}
   155→        hideOpenAction={hideOpenAction}
   156→      />
   157→    );
   158→  }
   159→
   160→  // ── Generic website URL (default) ──────────────────────────────────────────
   161→  return (
   162→    <WebsiteCard
   163→      content={content}
   164→      onOpenContent={onOpenContent}
   165→      isDeactivated={isDeactivated}
   166→      hideOpenAction={hideOpenAction}
   167→    />
   168→  );
   169→});
   170→
   171→export default ContentCard;
