    42→function formatRelativeTime(isoString: string): string {
    43→  const diff = Date.now() - new Date(isoString).getTime();
    44→  const mins = Math.floor(diff / 60000);
    45→  if (mins < 60) return `${mins}m ago`;
    46→  const hrs = Math.floor(mins / 60);
