import { View, Text, StyleSheet } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import Animated, { FadeInDown } from "react-native-reanimated";

interface Props {
  offlineMode: boolean;
  hasOwner: boolean;
  isDeactivated: boolean;
  deactivationMsg: string | null;
  isDark: boolean;
  colors: any;
}

export function QrHeaderBanners({ offlineMode, hasOwner, isDeactivated, deactivationMsg, isDark, colors }: Props) {
  return (
    <>
      {!offlineMode && !hasOwner && (
        <Animated.View entering={FadeInDown.delay(30).duration(260)}>
          <View style={[styles.externalBadge, {
            backgroundColor: isDark ? "#1a1208" : "#fffbeb",
            borderColor: "#f59e0b30",
          }]}>
            <Ionicons name="scan-outline" size={14} color="#f59e0b" />
            <Text style={[styles.externalBadgeText, { color: "#f59e0b" }]}>
              External QR Code · Scanned from the wild
            </Text>
          </View>
        </Animated.View>
      )}

      {isDeactivated && (
        <Animated.View entering={FadeInDown.delay(30).duration(260)}>
          <View style={[styles.deactivatedBanner, { borderColor: "#ef444440" }]}>
            <LinearGradient
              colors={["rgba(239,68,68,0.18)", "rgba(239,68,68,0.08)"]}
              style={StyleSheet.absoluteFill}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
            />
            <View style={styles.deactivatedIconWrap}>
              <Ionicons name="ban" size={22} color="#EF4444" />
            </View>
            <View style={{ flex: 1 }}>
              <Text style={[styles.deactivatedTitle, { color: colors.text }]}>QR Code Deactivated</Text>
              <Text style={[styles.deactivatedSub, { color: colors.textSecondary }]}>
                {deactivationMsg || "The owner has turned off this QR code. Links and actions are disabled."}
              </Text>
            </View>
          </View>
        </Animated.View>
      )}
    </>
  );
}

const styles = StyleSheet.create({
  externalBadge: {
    flexDirection: "row",
    alignItems: "center",
    gap: 6,
    borderRadius: 10,
    borderWidth: 1,
    paddingHorizontal: 12,
    paddingVertical: 7,
    marginBottom: 12,
    alignSelf: "flex-start",
  },
  externalBadgeText: {
    fontSize: 12,
    fontFamily: "Inter_600SemiBold",
    letterSpacing: 0.2,
  },
  deactivatedBanner: {
    flexDirection: "row",
    alignItems: "center",
    gap: 12,
    borderRadius: 14,
    borderWidth: 1,
    padding: 14,
    marginBottom: 12,
    overflow: "hidden",
  },
  deactivatedIconWrap: {
    width: 40,
    height: 40,
    borderRadius: 12,
    backgroundColor: "rgba(239,68,68,0.12)",
    alignItems: "center",
    justifyContent: "center",
    flexShrink: 0,
  },
  deactivatedTitle: {
    fontSize: 14,
    fontFamily: "Inter_700Bold",
    marginBottom: 2,
  },
  deactivatedSub: {
    fontSize: 12,
    fontFamily: "Inter_400Regular",
    lineHeight: 17,
  },
});

import Animated, { FadeInDown } from "react-native-reanimated";
import { VerdictBanner } from "@/features/qr-detail/components/VerdictBanner";
import AdvisoryDisclaimer from "@/features/qr-detail/components/AdvisoryDisclaimer";
import OwnerCircleRow from "@/features/qr-detail/components/OwnerCircleRow";

interface Props {
  verdict: any;
  offlineMode: boolean;
  ownerInfo: any;
  onOpenOwnerSheet: () => void;
}

export function QrVerdictSection({ verdict, offlineMode, ownerInfo, onOpenOwnerSheet }: Props) {
  return (
    <>
      <Animated.View entering={FadeInDown.delay(40).duration(260)}>
        <VerdictBanner verdict={verdict} offlineMode={offlineMode} />
      </Animated.View>

      {ownerInfo?.isBranded && (
        <OwnerCircleRow
          ownerInfo={ownerInfo as any}
          onPress={onOpenOwnerSheet}
        />
      )}

      <Animated.View entering={FadeInDown.delay(60).duration(260)}>
        <AdvisoryDisclaimer />
      </Animated.View>
    </>
  );
}

import Animated, { FadeInDown } from "react-native-reanimated";
import ContentCard from "@/features/qr-detail/components/ContentCard";
import SafetyWarningCard from "@/features/qr-detail/components/SafetyWarningCard";
import EvidenceCard from "@/features/qr-detail/components/EvidenceCard";
import ExternalQrBanner from "@/features/qr-detail/components/ExternalQrBanner";

interface Props {
  content: string;
  contentType: string;
  parsedPayment: any;
  isDeactivated: boolean;
  onOpenContent: () => void;
  templateKey?: string;
  paymentSafety?: any;
  urlSafety?: any;
  offlineBlacklistMatch?: { matched: boolean; reason?: string };
  isBranded?: boolean;
  offlineMode?: boolean;
  hasOwner?: boolean;
  user?: any;
}

export function QrContentSection({
  content,
  contentType,
  parsedPayment,
  isDeactivated,
  onOpenContent,
  templateKey,
  paymentSafety,
  urlSafety,
  offlineBlacklistMatch,
  isBranded,
  offlineMode,
  hasOwner,
  user,
}: Props) {
  const paymentWarnings = (paymentSafety?.warnings ?? []).filter(
    (w: string) => !w.toLowerCase().startsWith("pre-filled amount")
  );

  return (
    <>
      <Animated.View entering={FadeInDown.delay(70).duration(260)}>
        <ContentCard
          content={content}
          contentType={contentType}
          parsedPayment={parsedPayment}
          isDeactivated={isDeactivated}
          onOpenContent={onOpenContent}
          hideOpenAction={false}
          templateKey={templateKey}
        />
      </Animated.View>

      {contentType === "payment" && paymentSafety?.isSuspicious && paymentWarnings.length > 0 && (
        <Animated.View entering={FadeInDown.delay(80).duration(260)}>
          <SafetyWarningCard
            riskLevel={paymentSafety.riskLevel as "caution" | "dangerous"}
            warnings={paymentWarnings}
            title={paymentSafety.riskLevel === "dangerous" ? "Payment Security Warning" : "Payment Security Notice"}
          />
        </Animated.View>
      )}

      {contentType === "payment" && paymentSafety?.evidence && paymentSafety.evidence.length > 0 && (
        <Animated.View entering={FadeInDown.delay(80).duration(260)}>
          <EvidenceCard title="Payment Analysis" evidence={paymentSafety.evidence} />
        </Animated.View>
      )}

      {urlSafety?.isSuspicious && (
        <Animated.View entering={FadeInDown.delay(80).duration(260)}>
          <SafetyWarningCard
            riskLevel={urlSafety.riskLevel as "caution" | "dangerous"}
            warnings={urlSafety.warnings}
            title={urlSafety.riskLevel === "dangerous" ? "Destination Warning" : "Proceed with Caution"}
          />
        </Animated.View>
      )}

      {urlSafety?.evidence && urlSafety.evidence.length > 0 && (
        <Animated.View entering={FadeInDown.delay(90).duration(260)}>
          <EvidenceCard title="URL Analysis" evidence={urlSafety.evidence} />
        </Animated.View>
      )}

      {!isBranded && !offlineMode && !hasOwner && (
        <Animated.View entering={FadeInDown.delay(80).duration(260)}>
          <ExternalQrBanner />
        </Animated.View>
      )}
    </>
  );
}

import Animated, { FadeInDown } from "react-native-reanimated";
import TrustScoreCard from "@/features/qr-detail/components/TrustScoreCard";

interface Props {
  offlineMode: boolean;
  trust: any;
  reportCounts: any;
  totalScans: number;
  isQrOwner: boolean;
  followCount: number;
  followersModalOpen: boolean;
  onOpenFollowers: () => void;
  manipulationWarning: any;
  scanCountFrozen?: boolean;
  ownerScanCount?: number;
  user: any;
  delay?: number;
}

export function QrTrustSection({
  offlineMode,
  trust,
  reportCounts,
  totalScans,
  isQrOwner,
  followCount,
  followersModalOpen,
  onOpenFollowers,
  manipulationWarning,
  scanCountFrozen,
  ownerScanCount,
  user,
  delay = 90,
}: Props) {
  if (offlineMode) return null;

  return (
    <Animated.View entering={FadeInDown.delay(delay).duration(260)}>
      <TrustScoreCard
        trustInfo={trust}
        reportCounts={reportCounts}
        totalScans={totalScans}
        isQrOwner={user ? isQrOwner : false}
        followCount={followCount}
        followersModalOpen={user ? followersModalOpen : false}
        onOpenFollowers={user ? onOpenFollowers : () => {}}
        manipulationWarning={manipulationWarning}
        scanCountFrozen={scanCountFrozen}
        ownerScanCount={user && isQrOwner ? ownerScanCount : undefined}
      />
    </Animated.View>
  );
}

import { View, Text } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import Animated, { FadeInDown } from "react-native-reanimated";
import ReportGrid from "@/features/qr-detail/components/ReportGrid";
import SafetyWarningCard from "@/features/qr-detail/components/SafetyWarningCard";
import EvidenceCard from "@/features/qr-detail/components/EvidenceCard";
import { offlineSectionStyles } from "@/features/qr-detail/styles";

const REPORT_LABELS: Record<string, string> = { safe: "Safe", scam: "Scam", fake: "Fake", spam: "Spam" };
const REPORT_ICONS: Record<string, keyof typeof Ionicons.glyphMap> = {
  safe: "shield-checkmark", scam: "warning", fake: "close-circle", spam: "mail-unread",
};

interface Props {
  user: any;
  offlineMode: boolean;
  reportCounts: any;
  userReport: any;
  isPayment: boolean;
  handleReport: (type: string) => boolean;
  showToast: (msg: string, icon: keyof typeof Ionicons.glyphMap) => void;
  onLayout?: (e: any) => void;
  colors: any;
  urlSafety?: any;
  offlineBlacklistMatch?: { matched: boolean; reason?: string };
  showUrlSafety?: boolean;
  delay?: number;
}

export function QrReportSection({
  user,
  offlineMode,
  reportCounts,
  userReport,
  isPayment,
  handleReport,
  showToast,
  onLayout,
  colors,
  urlSafety,
  offlineBlacklistMatch,
  showUrlSafety = false,
  delay = 100,
}: Props) {
  if (!user) return null;

  return (
    <>
      <Animated.View
        entering={FadeInDown.delay(delay).duration(260)}
        onLayout={onLayout}
      >
        {offlineMode ? (
          <View style={offlineSectionStyles.row}>
            <Ionicons name="cloud-offline-outline" size={16} color={colors.textMuted} />
            <Text style={[offlineSectionStyles.text, { color: colors.textMuted }]}>
              Connect to the internet to submit your rating
            </Text>
          </View>
        ) : (
          <ReportGrid
            reportCounts={reportCounts}
            userReport={userReport}
            isLoggedIn={true}
            isPayment={isPayment}
            onReport={(type) => {
              const reported = handleReport(type);
              if (!reported) return;
              showToast(`Voted ${REPORT_LABELS[type] ?? type}`, REPORT_ICONS[type] ?? "flag");
            }}
          />
        )}
      </Animated.View>

      {showUrlSafety && (
        <>
          {((urlSafety?.isSuspicious) || offlineBlacklistMatch?.matched) && (
            <Animated.View entering={FadeInDown.delay(delay).duration(260)}>
              {urlSafety?.isSuspicious && (
                <SafetyWarningCard
                  riskLevel={urlSafety.riskLevel as "caution" | "dangerous"}
                  warnings={urlSafety.warnings}
                  title={urlSafety.riskLevel === "dangerous" ? "Dangerous URL Detected" : "Proceed with Caution"}
                />
              )}
              {offlineBlacklistMatch?.matched && (
                <SafetyWarningCard
                  riskLevel="dangerous"
                  warnings={[`Known scam pattern: ${offlineBlacklistMatch.reason}`]}
                  title="Known Scam Pattern"
                />
              )}
            </Animated.View>
          )}

          {urlSafety?.evidence && urlSafety.evidence.length > 0 && (
            <Animated.View entering={FadeInDown.delay(delay + 10).duration(260)}>
              <EvidenceCard title="URL Analysis" evidence={urlSafety.evidence} />
            </Animated.View>
          )}
        </>
      )}
    </>
  );
}

